<script setup>
import { nextTick, reactive, ref } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { supplierCreateDraft, toSupplierCreatePayload, validateSupplierCreateDraft } from '../domain/supplier-list.mjs';
const props=defineProps({saving:Boolean,serverError:String});const emit=defineEmits(['cancel','save']);const draft=reactive(supplierCreateDraft());const errors=reactive({});const nameInput=ref(null);const invoices=['','Hóa đơn VAT','Hóa đơn bán hàng','Không yêu cầu'].map((value)=>({value,label:value||'Chưa xác định'}));function validate(){const next=validateSupplierCreateDraft(draft);Object.keys(errors).forEach((key)=>delete errors[key]);Object.assign(errors,next);return next;}async function submit(){if(Object.keys(validate()).length){await nextTick();nameInput.value?.focus();return;}emit('save',toSupplierCreatePayload(draft));}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[880px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" novalidate @submit.prevent="submit"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">Thêm nhà cung cấp</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Thiết lập nhận diện và đầu mối. Phí dịch vụ, đặt cọc và giao dịch được quản lý trong luồng có kiểm quyền riêng.</p></div><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton></header><div class="grid gap-4 p-5 sm:grid-cols-2"><label class="block sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Tên nhà cung cấp <span class="text-[var(--mds-danger)]">*</span></span><MInput ref="nameInput" v-model="draft.name" :error="errors.name" :disabled="saving" placeholder="Nhập tên nhà cung cấp"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Ngành nghề</span><MInput v-model="draft.industry" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Dịch vụ cung cấp</span><MInput v-model="draft.services" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Số điện thoại</span><MInput v-model="draft.contact_phone" type="tel" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Email liên hệ</span><MInput v-model="draft.contact_email" type="email" :error="errors.contact_email" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Mã số thuế</span><MInput v-model="draft.tax_code" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Loại hóa đơn</span><MSelect v-model="draft.invoice_type" :options="invoices" :disabled="saving"/></label><label class="sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Địa chỉ</span><MInput v-model="draft.address" :disabled="saving"/></label><label class="sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Liên kết nhóm đặt hàng</span><MInput v-model="draft.order_group_link" type="url" placeholder="https://…" :disabled="saving"/></label><label class="sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :rows="3" maxlength="2000" :disabled="saving"/></label></div><p v-if="serverError" role="alert" class="mx-5 mb-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ serverError }}</p><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" :disabled="saving" @click="submit">Tạo nhà cung cấp</MButton></footer></form></section></template>
